      "evidence": ["article:p19", "article.xml/Table 3/R1C10", "mmc1.docx/table6/R2C5"],
      "explanation": "The comparison pairs organoid drug sensitivity for a regimen with the patient's clinical response to that regimen."
    },
    "platform": {
      "value": "organoid",
      "evidence": ["article:p27", "article.xml/Table 3/R1C12"],
      "explanation": "All evaluated predictions came from patient-derived lung cancer organoid drug testing."
    },
    "readout": {
