    },
    "direction": {
      "value": "unknown",
      "evidence": ["article:p19"],
      "explanation": "Assay-specific sensitivity directions and cutoffs varied among studies and are not supplied in a common rule."
    },
    "threshold_rule": {
      "value": "unknown",
      "evidence": ["article:p19"],
      "explanation": "The article states that each study's assay definition and cutoff were used, but does not provide a common threshold or all study cutoffs."
    },
    "threshold_timing": {
      "value": "not_reported",
      "evidence": ["article:p19"],
      "explanation": "The source does not report whether the study-specific cutoffs were prespecified or outcome optimized."
    },
    "patient_mapping": {
      "value": "absent",
      "evidence": ["article:p32"],
      "explanation": "The authors explicitly state that individual data were unavailable in the pooled analysis."
    },
    "regimen_match": {
      "value": "partial",
      "evidence": ["article.xml/Table 3/R2C10", "article.xml/Table 3/R3C10", "article.xml/Table 3/R4C10", "article.xml/Table 3/R5C10"],
      "explanation": "Some studies identify matched targeted therapies or chemotherapy, while one study reports no regimen and regimens are aggregated."
    },
    "n_units": {
      "value": None,
      "evidence": ["article:p27", "article.xml/Table 3/R2C11", "article.xml/Table 3/R3C11", "article.xml/Table 3/R4C11", "article.xml/Table 3/R5C11", "mmc1.docx/table6/R3C4", "mmc1.docx/table6/R4C4"],
      "explanation": "The pooled accuracy is reported, but the tables do not provide a reconciled row-level denominator for the exact pooled comparison; the displayed study-level and regimen-level totals are not consistently defined."
    },
    "split": {
      "value": "none",
      "evidence": ["article:p19", "article:p27"],
      "explanation": "This is a meta-analysis of paired organoid-test and clinical-outcome concordance, not a trained model with a discovery and test split."
    }
  },
  "headline": {
    "metric": "accuracy",
    "reported": 0.907,
    "reported_evidence": ["article:p27", "article:p3"],
    "threshold": None,
    "op": "==",
    "score_direction": "higher",
    "records": [],
    "blocked_reason": "Missing row-level, independently identifiable paired evidence for each evaluated patient-regimen: each organoid sensitive/resistant assay result, its assay-specific cutoff, the corresponding clinical responder/nonresponder outcome, and a reconciled denominator. Only study-level aggregate rates/counts are available, and the article states that individual data were unavailable."
  },
  "notes": [
    "A global clinical predictive headline exists: pooled organoid drug-test accuracy was reported as 90.7% (95% CI 77.4%-99.2%).",
    "The contract is blocked rather than computationally reconstructed because aggregate study-level accuracy and response counts are not sufficient to create the required patient-regimen records.",
    "The abstract text contains a typographical CI endpoint of 9.2%, while the results section reports 99.2%."
  ]
}"}
